const ProductInfo& ScriptSession::buildingUpgradeInfo(std::uint32_t from,std::uint32_t to) {auto key=std::pair{from,to};if(auto found=buildingUpgradeProducts_.find(key);found!=buildingUpgradeProducts_.end())return found->second;auto info=product(to);auto& previous=product(from);info.gold=std::max(0,info.gold-previous.gold);info.lumber=std::max(0,info.lumber-previous.lumber);return buildingUpgradeProducts_.emplace(key,std::move(info)).first->second;}
bool ScriptSession::upgradeAllowed(const UnitState& u,const ProductInfo& info,std::string& reason) {
    if(u.removing || u.paused || u.abilitiesDisabled() || u.hidden() || !u.stationaryBuilding() || u.illusion || u.construction || u.buildingUpgrade || u.unsummon || number(u.life)<=0){reason="该建筑当前无法升级";return false;}if(!u.production.empty()){reason="需要先完成生产或研究队列";return false;}if(std::find(u.upgradeables.begin(),u.upgradeables.end(),info.type)==u.upgradeables.end() || definitions().property(info.type,"ubdg","0")!="1"){reason="无效的建筑升级";return false;}if(!productAllowed(u.owner,info,reason,false))return false;auto& states=config_.players[u.owner].states;int extra=std::max(0,info.food-u.foodUsed);if(extra && states[5]>std::min(states[4],states[6])-extra){reason="人口不足";return false;}return true;
}
bool ScriptSession::upgradeBuilding(std::uint32_t id,std::uint32_t type) {
    if(!alive(id,NativeKind::Unit) || productionTicket_==UINT64_MAX)return false;auto u=units_.at(id);if(std::find(u->upgradeables.begin(),u->upgradeables.end(),type)==u->upgradeables.end())return false;auto& info=buildingUpgradeInfo(u->type,type);std::string reason;if(!upgradeAllowed(*u,info,reason))return false;if(!cancelCombat(*u) || productionTicket_==UINT64_MAX)return false;BuildingUpgrade job;job.type=type;job.gold=info.gold;job.lumber=info.lumber;job.food=u->foodCounted?std::max(0,info.food-u->foodUsed):0;job.duration=std::max(1./32,double(info.trainTime));job.ticket=++productionTicket_;u->buildingUpgrade=job;u->currentOrder=type;u->animation="Upgrade";u->animationTime=0;auto owner=u->owner;auto& states=config_.players[owner].states;int gold=states[1],lumber=states[2];states[1]-=job.gold;states[2]-=job.lumber;adjustFood(owner,job.food,0);playerChange(owner,1,gold,gold-job.gold,false);playerChange(owner,2,lumber,lumber-job.lumber,false);if(alive(id,NativeKind::Unit) && u->buildingUpgrade && u->buildingUpgrade->ticket==job.ticket)unitEvent(id,29,66);return true;
}
bool ScriptSession::cancelBuildingUpgrade(std::uint32_t id,bool refund) {
    if(!alive(id,NativeKind::Unit))return false;auto u=units_.at(id);if(!u->buildingUpgrade || u->removing)return false;auto job=*u->buildingUpgrade;u->buildingUpgrade.reset();u->currentOrder=0;u->animation.clear();u->animationTime=0;auto owner=u->owner;float rate=refund?gameplayNumber("UpgradeRefundRate",.75f):0;if(rate<0 || rate>1)throw std::runtime_error("Invalid building upgrade refund rate");auto& states=config_.players[owner].states;int gold=states[1],lumber=states[2];int nextGold=states[1]=int(std::min(std::int64_t(INT_MAX),std::int64_t(gold)+std::int64_t(std::floor(job.gold*rate)))),nextLumber=states[2]=int(std::min(std::int64_t(INT_MAX),std::int64_t(lumber)+std::int64_t(std::floor(job.lumber*rate))));adjustFood(owner,-job.food,0);playerChange(owner,1,gold,nextGold,false);playerChange(owner,2,lumber,nextLumber,false);unitEvent(id,30,67);return true;
}
void ScriptSession::finishBuildingUpgrade(std::uint32_t id) {
    if(!alive(id,NativeKind::Unit))return;auto u=units_.at(id);if(!u->buildingUpgrade || u->removing || number(u->life)<=0)return;auto job=*u->buildingUpgrade;UnitState next,previous;previous.owner=next.owner=u->owner;initializeUnitType(previous,u->type);initializeUnitType(next,job.type);initializeHero(next);initializeCommerce(next);refreshResearch(next);initializeHarvest(next);for(auto [ability,level]:u->abilities)if(!previous.abilities.contains(ability) || (u->permanentAbilities.contains(ability) && u->permanentAbilities.at(ability)))next.abilities[ability]=level;for(auto [ability,level]:previous.abilities)if(!u->abilities.contains(ability))next.abilities.erase(ability);
    float hp=number(next.maxLife)-number(previous.maxLife)-u->technology.health,mp=number(next.maxMana)-number(previous.maxMana)-u->technology.mana;int beforeUsed=u->foodCounted?u->foodUsed:0,beforeMade=u->foodCounted?u->foodMade:0;u->buildingUpgrade.reset();u->type=next.type;u->name=std::move(next.name);u->model=std::move(next.model);u->icon=std::move(next.icon);u->maxLife=real(std::max(1.f,number(u->maxLife)+hp));u->life=real(std::clamp(number(u->life)+hp,1.f,number(u->maxLife)));u->maxMana=real(std::max(0.f,number(u->maxMana)+mp));u->mana=real(std::clamp(number(u->mana),0.f,number(u->maxMana)));u->moveSpeed=next.moveSpeed;u->defaultMoveSpeed=next.defaultMoveSpeed;u->turnSpeed=std::clamp(u->turnSpeed+next.defaultTurnSpeed-previous.defaultTurnSpeed,0.f,3.f);u->defaultTurnSpeed=next.defaultTurnSpeed;u->propWindow=std::clamp(u->propWindow+next.propWindow-previous.propWindow,0.f,6.28318531f);u->defaultPropWindow=next.defaultPropWindow;u->acquireRange=next.acquireRange;u->scale=next.scale;u->selectionSize=next.selectionSize;u->collision=next.collision;u->movementType=std::move(next.movementType);u->race=next.race;u->level=next.level;u->abilities=std::move(next.abilities);std::erase_if(u->autocast,[&](auto& entry){return !u->abilities.contains(entry.first);});for(auto [ability,on]:next.autocast)u->autocast.try_emplace(ability,on);u->trainables=std::move(next.trainables);u->researches=std::move(next.researches);u->upgrades=std::move(next.upgrades);u->upgradeables=std::move(next.upgradeables);u->buildables=std::move(next.buildables);u->stock=std::move(next.stock);u->technology=std::move(next.technology);u->healthRegen=next.healthRegen;u->manaRegen=next.manaRegen;u->regenType=std::move(next.regenType);u->foodUsed=next.foodUsed;u->foodMade=next.foodMade;u->currentOrder=0;u->animation="Stand";u->animationTime=0;u->animationIndex.reset();u->animationQueue.clear();u->blightAbility=0;unitFootprint(*u);auto owner=u->owner;adjustFood(owner,(u->foodCounted?u->foodUsed:0)-beforeUsed-job.food,(u->foodCounted?u->foodMade:0)-beforeMade);unitEvent(id,31,68);++fogRevision_;
}
void ScriptSession::buildingUpgrades(double delta) {std::vector<std::uint32_t> ids;for(auto& [id,u]:units_)if(u->buildingUpgrade)ids.push_back(id);for(auto id:ids){if(!alive(id,NativeKind::Unit))continue;auto u=units_.at(id);if(!u->buildingUpgrade || u->paused || u->abilitiesDisabled() || u->removing || number(u->life)<=0)continue;u->buildingUpgrade->elapsed=std::min(u->buildingUpgrade->duration,u->buildingUpgrade->elapsed+delta);if(u->buildingUpgrade->elapsed>=u->buildingUpgrade->duration)finishBuildingUpgrade(id);}}
